recipes.code:
{
  "inputs": [
    {
      "id": "taisly-api-key",
      "type": "promptString",
      "description": "Optional. Run `taisly setup --agent <agent-slug>` to store a local Taisly agent credential, or set this manual API key from Taisly Settings.",
      "password": true
    }
  ],
  "servers": {
    "agent": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@taisly/agent@0.2.7"
      ],
      "env": {
        "TAISLY_API_KEY": "${input:taisly-api-key}"
      }
    }
  }
}
